export const deliveryProfile={producerId:'front',architecture:'amd64',materials:['build','image.manifest','image.config','data.plan','run.instructions','collaboration.record','role.configuration','image.layer.0'].map((key,index)=>({key,path:'.artifacts/delivery/'+index+'.bin'}))};
